           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (case when coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS1")), ''))))), upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS2")), ''))))), upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS3")), ''))))), upper(trim(to_varchar(((nullif(trim(to_varchar("CITY")), '')))))), upper(trim(to_varchar(((nullif(trim(to_varchar("DISTRICT")), '')))))), upper(trim(to_varchar((nullif(trim(to_varchar("STATE")), ''))))), upper(trim(to_varchar((nullif(trim(to_varchar("PINCODE")), ''))))), upper(trim(to_varchar((nullif(trim(to_varchar("COUNTRY")), '')))))) is null then null else md5(concat_ws('|', coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS1")), ''))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS2")), ''))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("ADDRESS3")), ''))))), ''), coalesce(upper(trim(to_varchar(((nullif(trim(to_varchar("CITY")), '')))))), ''), coalesce(upper(trim(to_varchar(((nullif(trim(to_varchar("DISTRICT")), '')))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("STATE")), ''))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("PINCODE")), ''))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("COUNTRY")), ''))))), ''))) end) AS VARCHAR))), '')) as LOCATION_HKEY
