----------------------------------------------------------------------------------------
-- 2. MAXIMUS — LNK_PARTY_LOCATION -- (b) orphan links (link FK -> hub)   [Implemented]
-- Link rows scoped to RECORD_SOURCE 'MAXIMUS_%'; every FK must exist in its hub (any
-- project's rows -- shared vault). FKs: PARTY_HKEY -> HUB_PARTY, LOCATION_HKEY ->
-- HUB_LOCATION.
----------------------------------------------------------------------------------------
select 'MAXIMUS' as project, 'LNK_PARTY_LOCATION' as link, 'PARTY_HKEY' as fk_column, 'HUB_PARTY' as hub,
       count(*) as link_rows,
       count_if(l.PARTY_HKEY is null) as null_fk_rows,
       count_if(l.PARTY_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.PARTY_HKEY is not null and h.k is null, to_varchar(l.PARTY_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_LOCATION l
  left join (select distinct PARTY_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_PARTY) h on h.k = l.PARTY_HKEY
 where startswith(l.RECORD_SOURCE, 'MAXIMUS_')
union all
select 'MAXIMUS' as project, 'LNK_PARTY_LOCATION' as link, 'LOCATION_HKEY' as fk_column, 'HUB_LOCATION' as hub,
       count(*) as link_rows,
       count_if(l.LOCATION_HKEY is null) as null_fk_rows,
       count_if(l.LOCATION_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.LOCATION_HKEY is not null and h.k is null, to_varchar(l.LOCATION_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_LOCATION l
  left join (select distinct LOCATION_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_LOCATION) h on h.k = l.LOCATION_HKEY
 where startswith(l.RECORD_SOURCE, 'MAXIMUS_')
order by fk_column;



