----------------------------------------------------------------------------------------
-- 4. MAXIMUS — LNK_PARTY_RELATIONSHIP -- (a) missing links (RAW -> link)   [Implemented]
-- 1 RAW feed(s): hubfeed_party_relationship_lnk <- stg2_mp__pd_relparty. FKs: PARTY_HKEY
-- -> HUB_PARTY, RELATED_PARTY_HKEY -> HUB_PARTY. A RAW relationship counts only when
-- every FK key is present (automate_dv.link does not load a row with a NULL FK). Link
-- hash keys are recomputed from RAW with the stg2 NK expressions (automate_dv 0.11.5
-- MD5_BINARY formula).
----------------------------------------------------------------------------------------
-- SQL query (a) -- counts per feed
with src as (
    -- via hubfeed_party_relationship_lnk <- stg2_mp__pd_relparty
    select 'hubfeed_party_relationship_lnk <- stg2_mp__pd_relparty' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_PARTY_RELATIONSHIP|' || (((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) || '||' || ((nullif(trim(to_varchar("PARTY_CODE")), '')))) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("PARTY_CODE")), ''))) AS VARCHAR))), '')) as RELATED_PARTY_HKEY
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_RELATED_PARTY
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("PARTY_CODE")), ''))) AS VARCHAR))), '')) is not null
)
select 'MAXIMUS' as project, 'LNK_PARTY_RELATIONSHIP' as link,
       coalesce(src.src_feed, '== TOTAL (distinct across feeds) ==') as src_feed,
       count(distinct src.link_hkey) as source_relationships,
       count(distinct iff(l.k is not null, src.link_hkey, null)) as present_in_link,
       source_relationships - present_in_link as missing_links,
       iff(missing_links = 0, 'PASS', 'FAIL') as status
  from src
  left join (select distinct PARTY_RELATIONSHIP_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_RELATIONSHIP) l on l.k = src.link_hkey
 group by grouping sets ((src.src_feed), ())
 order by grouping(src.src_feed) desc, src.src_feed;

-- SQL query (a) drill-down -- first 100 missing relationships
with src as (
    -- via hubfeed_party_relationship_lnk <- stg2_mp__pd_relparty
    select 'hubfeed_party_relationship_lnk <- stg2_mp__pd_relparty' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_PARTY_RELATIONSHIP|' || (((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) || '||' || ((nullif(trim(to_varchar("PARTY_CODE")), '')))) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("PARTY_CODE")), ''))) AS VARCHAR))), '')) as RELATED_PARTY_HKEY
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_RELATED_PARTY
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("PARTY_CODE")), ''))) AS VARCHAR))), '')) is not null
)
select 'MAXIMUS' as project, 'LNK_PARTY_RELATIONSHIP' as link, src_feed, to_varchar(link_hkey, 'HEX') as missing_link_hkey,
       to_varchar(PARTY_HKEY, 'HEX') as PARTY_HKEY, to_varchar(RELATED_PARTY_HKEY, 'HEX') as RELATED_PARTY_HKEY
  from src
 where not exists (select 1 from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_RELATIONSHIP l where l.PARTY_RELATIONSHIP_HKEY = src.link_hkey)
 order by src_feed
 limit 100;



