with src as (
    -- via hubfeed_party_relationship_lnk <- stg2_mp__pd_relparty
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_PARTY_RELATIONSHIP|' || (((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) || '||' || ((nullif(trim(to_varchar("PARTY_CODE")), '')))) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("PARTY_CODE")), ''))) AS VARCHAR))), '')) as RELATED_PARTY_HKEY
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_RELATED_PARTY
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("PARTY_CODE")), ''))) AS VARCHAR))), '')) is not null
)
select 'MAXIMUS' as project, 'LNK_PARTY_RELATIONSHIP' as link, l.RECORD_SOURCE,
       count(*) as link_rows,
       count_if(k.link_hkey is null) as unexpected_links,
       array_slice(array_agg(iff(k.link_hkey is null, to_varchar(l.PARTY_RELATIONSHIP_HKEY, 'HEX'), null)), 0, 3) as examples
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_RELATIONSHIP l
  left join (select distinct link_hkey from src) k on k.link_hkey = l.PARTY_RELATIONSHIP_HKEY
 where startswith(l.RECORD_SOURCE, 'MAXIMUS_')
 group by l.RECORD_SOURCE
 order by l.RECORD_SOURCE;



----------------------------------------------------------------------------------------
-- 7. MAXIMUS — LNK_PARTY_ROLE -- (a) missing links (RAW -> link)   [Implemented]
-- 1 RAW feed(s): hubfeed_party_role_lnk <- stg2_mp__pd_prop_sp_pv. FKs: PARTY_HKEY ->
-- HUB_PARTY. A RAW relationship counts only when every FK key is present
-- (automate_dv.link does not load a row with a NULL FK). Link hash keys are recomputed
-- from RAW with the stg2 NK expressions (automate_dv 0.11.5 MD5_BINARY formula).
----------------------------------------------------------------------------------------
-- SQL query (a) -- counts per feed
with src as (
    -- via hubfeed_party_role_lnk <- stg2_mp__pd_prop_sp_pv
    select 'hubfeed_party_role_lnk <- stg2_mp__pd_prop_sp_pv' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_PARTY_ROLE|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as PARTY_HKEY
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) is not null
)
select 'MAXIMUS' as project, 'LNK_PARTY_ROLE' as link,
       coalesce(src.src_feed, '== TOTAL (distinct across feeds) ==') as src_feed,
       count(distinct src.link_hkey) as source_relationships,
       count(distinct iff(l.k is not null, src.link_hkey, null)) as present_in_link,
       source_relationships - present_in_link as missing_links,
       iff(missing_links = 0, 'PASS', 'FAIL') as status
  from src
  left join (select distinct PARTY_ROLE_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_ROLE) l on l.k = src.link_hkey
 group by grouping sets ((src.src_feed), ())
 order by grouping(src.src_feed) desc, src.src_feed;

-- SQL query (a) drill-down -- first 100 missing relationships
with src as (
    -- via hubfeed_party_role_lnk <- stg2_mp__pd_prop_sp_pv
    select 'hubfeed_party_role_lnk <- stg2_mp__pd_prop_sp_pv' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_PARTY_ROLE|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as PARTY_HKEY
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) is not null
)
select 'MAXIMUS' as project, 'LNK_PARTY_ROLE' as link, src_feed, to_varchar(link_hkey, 'HEX') as missing_link_hkey,
       to_varchar(PARTY_HKEY, 'HEX') as PARTY_HKEY
  from src
 where not exists (select 1 from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_ROLE l where l.PARTY_ROLE_HKEY = src.link_hkey)
 order by src_feed
 limit 100;



----------------------------------------------------------------------------------------
-- 8. MAXIMUS — LNK_PARTY_ROLE -- (b) orphan links (link FK -> hub)   [Implemented]
-- Link rows scoped to RECORD_SOURCE 'MAXIMUS_%'; every FK must exist in its hub (any
-- project's rows -- shared vault). FKs: PARTY_HKEY -> HUB_PARTY.
----------------------------------------------------------------------------------------
select 'MAXIMUS' as project, 'LNK_PARTY_ROLE' as link, 'PARTY_HKEY' as fk_column, 'HUB_PARTY' as hub,
       count(*) as link_rows,
       count_if(l.PARTY_HKEY is null) as null_fk_rows,
       count_if(l.PARTY_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.PARTY_HKEY is not null and h.k is null, to_varchar(l.PARTY_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_ROLE l
  left join (select distinct PARTY_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_PARTY) h on h.k = l.PARTY_HKEY
 where startswith(l.RECORD_SOURCE, 'MAXIMUS_')
order by fk_column;



